function buildingInfoHTML(type,compact=false){const b=NS.BUILDINGS?.[type]||{label:type},cost=NS.V08?.BUILD_COSTS?.[type]||{},m=maintOf(type),meta=BUILD_META[type]||{},st=b.storage||{},storage=Object.entries(st).filter(([,v])=>Number(v)>0).map(([k,v])=>`${({food:'🌾',wood:'🪵',stone:'🪨',iron_ore:'⛏️',iron:'⚙️',tools:'🔧'}[k]||k)} ${v}`).join(' · ')||'없음';return`<div class="a4-building-info${compact?' compact':''}"><div class="a4-build-title"><strong>${esc(b.icon||'')} ${esc(b.label||type)}</strong><span>${esc(type)}</span></div><div class="small">${esc(b.desc||buildingEffect(type))}</div><div class="a4-info-grid"><span>해금 <b>${esc(unlockText(type))}</b></span><span>배치 <b>${esc(placementText(type))}</b></span><span>공간 <b>${Number(b.footprint||1).toFixed(1)}</b></span><span>비용 <b>${esc(fmtCost(cost))}</b></span><span>노동 <b>${laborOf(type)?laborOf(type).toFixed(0)+' 노동일':'상황별'}</b></span><span>저장 <b>${esc(storage)}</b></span>${meta.workers?`<span>근무 <b>${esc(meta.workers)}</b></span>`:''}<span>분기 유지 <b>🪵 ${m.wood.toFixed(2)} · 🪨 ${m.stone.toFixed(2)} · 👷 ${m.labor.toFixed(2)}</b></span></div><div class="a4-effect">${esc(buildingEffect(type))}</div></div>`;}
function buildingsPage(){const ids=Object.keys(NS.BUILDINGS||{}).filter(k=>!['water'].includes(k)),cats=[['주거',['house','row_house','collective_house']],['생산',['farmstead','ancient_farm','sawmill','quarry','deep_quarry','stoneworks','iron_mine','smelter','smithy']],['저장·상업',['granary','warehouse','storehouse','trading_post','merchant_guild','market','grand_market','harbor']],['행정·군사·기반',['town_hall','admin_office','outpost','palisade','road','barracks','training_ground','armory','schoolhouse']]];const used=new Set(cats.flatMap(x=>x[1]));const rest=ids.filter(x=>!used.has(x));if(rest.length)cats.push(['기타',rest]);return`<div class="codex-note"><strong>현재 규칙 기준 건물 백과</strong><br>버전별 변경 이력은 패치노트와 README에서 확인합니다. 건물을 누르면 해당 건물부터 이어지는 실제 상위 티어를 펼쳐봅니다.</div><div class="a4-building-layout"><div class="a4-building-list">${cats.map(([name,rows])=>`<h3>${name}</h3>${rows.filter(x=>NS.BUILDINGS[x]).map(x=>`<button class="a4-building-pick" data-a4-building="${x}">${esc(NS.BUILDINGS[x].icon||'')} <strong>${esc(NS.BUILDINGS[x].label||x)}</strong><span>${UPGRADE_GRAPH[x]?'상위 티어 있음':''}</span></button>`).join('')}`).join('')}</div><div id="a4BuildingDetail" class="a4-building-detail"></div></div>`;}
function prodPage(){const terrain=Object.entries(NS.TERRAIN||{}).filter(([,t])=>t.passable).map(([id,t])=>`<div class="codex-row"><div><strong>${esc(t.label)}</strong></div><div class="small">자연회복/일 🌾 ${t.regen.food} · 🪵 ${t.regen.wood} · 🪨 ${t.regen.stone}<br>채석장 효율 ${Number(QUARRY_FACTOR[id]||1).toFixed(2)}${DEEP_QUARRY_FACTOR[id]?` · 전문 채석장 ${DEEP_QUARRY_FACTOR[id].toFixed(2)}`:''}</div></div>`).join('');return`<div class="codex-note"><strong>현재 생산·소비 규칙</strong><br>기본 식량 소비는 0~14세 <b>0.30</b>, 15세 이상 <b>0.42</b>/3일 작업주기입니다. 농업 기술은 식량 채취 +8%와 고대 경작지를 해금합니다. 관개·윤작은 전국 평야 보너스를 주지 않고 고대 농장 개축만 해금합니다. 임업은 숲 목재 자연회복 +30%와 고대 제재소를 해금합니다.</div><h3>농업 시설</h3>${buildingInfoHTML('farmstead',true)}${buildingInfoHTML('ancient_farm',true)}<h3>목재 시설</h3>${buildingInfoHTML('sawmill',true)}<h3>석재 시설</h3>${buildingInfoHTML('quarry',true)}${buildingInfoHTML('deep_quarry',true)}<h3>지형</h3>${terrain}`;}
function logisticsPage(){return`<div class="codex-note"><strong>내부 물류</strong><br>실제 정착지 재고를 경로를 따라 이동하며 거리·지형·도로·행정효율이 운송 가능량과 경로비에 영향을 줍니다. 물류 이동은 자원을 생성하지 않습니다.</div><h3>도로</h3><div class="codex-row"><div><strong>🛣️ 고대 도로</strong><div class="small muted">단일 물리 도로 등급</div></div><div class="small">활성 도로 타일의 경로비 <b>×0.62</b>. 과거의 3단계 전역 도로 레벨은 사용하지 않습니다.</div></div><h3>장거리 교역</h3><div class="codex-note">교역소·상단 회관·항구·시장망이 실제 접점과 운송서비스를 형성합니다. 국제 운송비는 실제 Gold로 지불되며 도로와 항구가 운송비를 줄일 수 있습니다.</div>`;}
function economyPage(){return`<div class="codex-note"><strong>Gold 회계</strong><br>관측 통화량은 Nation Treasury + Settlement Market Gold + living Person Gold입니다. 건설 Gold와 개척 Gold는 보존형 순환을 거치며 새 Gold를 만들지 않습니다.</div><div class="codex-row"><strong>건설 Gold</strong><span class="small">성공한 Gold 비용의 75%를 목표 Settlement Market으로 환류, 25%만 실제 sink</span></div><div class="codex-row"><strong>개척 Gold</strong><span class="small">50% Pioneer 지갑 · 25% 출발 Settlement Market · 25% sink</span></div><div class="codex-row"><strong>국내경제</strong><span class="small">임금 → Person 소비 → 시장 → 세금/행정 levy → 공공지출</span></div>`;}
function militaryPage(){return`<div class="codex-note"><strong>실제 Person 군사</strong><br>현역·예비군·Formation은 모두 실제 Person을 참조합니다. 현역은 민간 노동에서 빠지며 별도의 합성 병력을 만들지 않습니다.</div><div class="codex-row"><strong>평시/전시 동원</strong><span class="small">평시 상비군은 성향·위협·식량에 따라 결정됩니다. 전쟁준비 목표는 개전 뒤 전시 목표로 승계되고 30일 보충동원이 작동합니다.</span></div><div class="codex-row"><strong>야전 Formation</strong><span class="small">평시 현역의 약 45%, 1개 전쟁 60%, 다중전쟁 70%를 야전군으로 배분하며 충분한 병력은 복수 Formation으로 분할됩니다.</span></div>${buildingInfoHTML('palisade',true)}<div class="codex-note">고대 방책의 점령 저항·방어화력은 <b>securing/점령 과정</b>에 적용되며 일반 야전전투의 지형 방어배율과는 별도입니다.</div>`;}
function socialPage(){return`<div class="codex-note"><strong>Person·문화·도시</strong><br>Person은 실제 생애·직업·가족·Gold·문화 혼합을 유지합니다. 문화는 1~3개 성분 비율로 보존되고 국가/정착지 문화는 실제 거주자를 집계합니다.</div><div class="codex-row"><strong>문화 생산 마찰</strong><span class="small">수도 기준 문화와의 불일치가 Person 생산에 최대 8% 마찰을 줄 수 있으며 전투·건강·출산·행복에는 직접 적용되지 않습니다.</span></div><div class="codex-row"><strong>정착지 성장</strong><span class="small">주거·일자리·통근·서비스·접근성으로 촌락/읍/도시성이 관측되며 행정등급과는 별개입니다.</span></div>`;}
function techPage(){return`<div class="codex-note"><strong>현재 기술 트리</strong><br>현재 ${NS.TECH_ORDER?.length||32}개 기술만 표시합니다. 아래 효과는 현재 코드가 사용하는 정식 설명이며 과거 버전 효과를 누적 표시하지 않습니다.</div>${(NS.TECH_ORDER||[]).map(id=>{const t=NS.TECH?.[id];if(!t)return'';return`<div class="codex-row"><div><strong>${esc(t.icon||'')} ${esc(t.label)}</strong><div class="small muted">${esc(t.branch||'')} · ${Number(t.cost||0)} Knowledge</div></div><div class="small">${esc(t.desc||'')}<br><span class="muted">${esc((t.effects||[]).join(' · ')||'직접 수치 효과 없음')}</span></div></div>`;}).join('')}`;}
function canonicalCodex(ui){const el=ui.q?.('codexContent');if(!el)return;const tab=ui._a4CodexTab||'build',pages={build:buildingsPage,prod:prodPage,logi:logisticsPage,economy:economyPage,military:militaryPage,social:socialPage,techs:techPage};el.innerHTML=`<div class="codex-tabs a4-codex-tabs">${[['build','건물'],['prod','생산·자원'],['logi','물류·도로'],['economy','경제·시장'],['military','군사·전쟁'],['social','사회·문화'],['techs','기술']].map(([k,l])=>`<button data-a4-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</div><div id="a4CodexPage">${pages[tab]()}</div>`;const renderTab=k=>{ui._a4CodexTab=k;el.querySelectorAll('[data-a4-tab]').forEach(b=>b.classList.toggle('active',b.dataset.a4Tab===k));const page=el.querySelector('#a4CodexPage');if(page)page.innerHTML=pages[k]();bindPage();};const bindPage=()=>{el.querySelectorAll('[data-a4-building]').forEach(b=>b.onclick=()=>{const type=b.dataset.a4Building,detail=el.querySelector('#a4BuildingDetail');if(!detail)return;detail.innerHTML=`<h3>업그레이드 계보</h3><div class="a4-chain">${chainFrom(type).map((x,i)=>`<span>${i?'→ ':''}${esc(NS.BUILDINGS[x]?.label||x)}</span>`).join('')}</div>${chainFrom(type).map(x=>buildingInfoHTML(x)).join('')}`;el.querySelectorAll('[data-a4-building]').forEach(x=>x.classList.toggle('active',x===b));});if(ui._a4CodexTab==='build'){const first=el.querySelector('[data-a4-building]');if(first)first.click();}};el.querySelectorAll('[data-a4-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.a4Tab));bindPage();ensure(ui.world).stats.codexCanonicalRenders++;}

