const recPrev=NS.Telemetry.prototype.record;
NS.Telemetry.prototype.record=function(type,w,payload={}){const r=recPrev.call(this,type,w,payload);try{const z=ensure(w);if(type==='WAR_DECLARED33')repairWarTargets(w,true);if(type==='BUILDING_UPGRADED'&&payload?.to==='ancient_farm')z.stats.ancientFarmUpgradesCompleted++;if(type==='BUILDING_STARTED'&&payload?.type==='sawmill')z.stats.sawmillStarts++;if(type==='BUILDING_COMPLETED'&&payload?.building==='sawmill')z.stats.sawmillCompleted++;if(type==='BUILDING_STARTED'&&payload?.type==='quarry'&&payload?.reason==='A4_ALL_TERRAIN_QUARRY'){z.stats.allTerrainQuarryStarts++;const t=w?.map?.get?.(Number(payload.tileId)),k=String(t?.terrain||'unknown');z.quarryStartsByTerrain[k]=Number(z.quarryStartsByTerrain[k]||0)+1;}}catch(e){console.error('V0.33F5A4 event bridge failed',e);}return r;};
const snapPrev=NS.Telemetry.prototype.snapshot;
NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snapPrev.call(this,w,reason,note);if(!s)return s;const z=ensure(w);Object.assign(s.global,{ancientFarmUpgradesStarted33F5A4:z.stats.ancientFarmUpgradesStarted,ancientFarmUpgradesCompleted33F5A4:z.stats.ancientFarmUpgradesCompleted,sawmillStarts33F5A4:z.stats.sawmillStarts,sawmillCompleted33F5A4:z.stats.sawmillCompleted,allTerrainQuarryStarts33F5A4:z.stats.allTerrainQuarryStarts,wartimeTargetInvariantRepairs33F5A4:z.stats.wartimeTargetInvariantRepairs});for(const row of s.villages||[]){const v=(w.villages||[]).find(x=>Number(x.id)===Number(row.id));if(!v)continue;row.ancientFarms33F5A4=countBuilding(v,w,'ancient_farm');row.sawmills33F5A4=countBuilding(v,w,'sawmill');row.sawmillWorkers33F5A4=(v.residents||[]).filter(p=>p.alive&&p.job==='목수'&&p.workBuildingType29==='sawmill').length;row.baseQuarries33F5A4=countBuilding(v,w,'quarry');}return s;};
const csvPrev=NS.Telemetry.prototype.snapshotsCSV;
NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvPrev.call(this),lines=base.split('\n');if(!lines.length)return base;const G=['ancientFarmUpgradesStarted33F5A4','ancientFarmUpgradesCompleted33F5A4','sawmillStarts33F5A4','sawmillCompleted33F5A4','allTerrainQuarryStarts33F5A4','wartimeTargetInvariantRepairs33F5A4'],R=['ancientFarms33F5A4','sawmills33F5A4','sawmillWorkers33F5A4','baseQuarries33F5A4'],q=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+[...G,...R].map(q).join(',');let i=1;for(const s of this.snapshots||[])for(const row of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+[...G.map(k=>s.global?.[k]),...R.map(k=>row?.[k])].map(q).join(',');}return lines.join('\n');};
const jsonPrev=NS.Telemetry.prototype.toJSON;
NS.Telemetry.prototype.toJSON=function(w){const d=jsonPrev.call(this,w),z=ensure(w);d.version=VERSION;d.v33F5A4=clone(z);Object.assign(d.worldSummary||{},{v33F5A4Revision:REV,codex33F5A4:'single canonical current-rules codex grouped by domain; historical version notes remain in patch notes/README',buildingTierCodex33F5A4:'building selection exposes actual upward upgrade chains and full tier metadata',irrigationCrop33F5A4:'retired duplicated irrigation/crop-rotation plain/grass and farm-worker numeric bonuses; IRRIGATION now unlocks farmstead -> ancient_farm',ancientFarm33F5A4:'upgrade-only production building: 10 farmer slots, food regeneration x1.60 and harvest up to x1.25 at full condition',forestrySawmill33F5A4:'FORESTRY keeps forest wood regeneration +30%, retires global +6% harvest, and unlocks a real sawmill with carpenter slots and worker-specific wood efficiency',quarryTerrain33F5A4:'base quarry can be built on any passable owned land; stone efficiency is much higher on rock/mountain; deep quarry remains rough-terrain specialization',palisadeCodex33F5A4:'codex now distinguishes security score, occupation resistance and securing defensive firepower from ordinary battle defense',wartimeTargetInvariant33F5A4:'wartime targets repaired so fieldTarget never exceeds activeTarget minus one core-garrison slot'});return d;};

