NS.World.from=function(d){if(d?.version===VERSION){const src=d,w=fromPrev({...d,version:'0.33F5A3'});w.v33f5a4=src.v33f5a4||w.v33f5a4;return attach(w,src);}return attach(fromPrev(d),d);};
function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const savePrev=NS.SaveSystem;(function(){const KEY='village-observer-v0-33f5a4',fallback=['village-observer-v0-33f5a3','village-observer-v0-33f5a2','village-observer-v0-33f5a1','village-observer-v0-33f5a','village-observer-v0-33f5p2'];NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v033F5A4-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v033F5A4-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){const x=w.telemetry.snapshotsCSV(),c=NS.V032E14?.validateCSV?.(x);if(c&&!c.ok)throw new Error(`CSV schema mismatch: expected ${c.columns} columns; bad rows ${c.bad.slice(0,8).join(', ')}`);dl(`village-observer-v033F5A4-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+x,'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attach(await savePrev.importMap(file));},async importScenario(file){return attach(await savePrev.importScenario(file));},exportScenario(w,meta=null){const x=NS.V032E14?.scenarioWrapper?.(w,meta);if(!x)return savePrev.exportScenario(w,meta);x.meta={...x.meta,intendedVersion:VERSION};x.world.testScenario={...x.meta};if(x.world.v32e11)x.world.v32e11.scenario={...x.meta};dl(`village-observer-v033F5A4-scenario-${x.meta.id}.json`,JSON.stringify(x));return x;}};})();

if(NS.UI){const setPrev=NS.UI.prototype.setWorld,headPrev=NS.UI.prototype.renderHeader,contentPrev=NS.UI.prototype.renderVillageContent;NS.UI.prototype.setWorld=function(w){return setPrev.call(this,attach(w));};NS.UI.prototype.renderHeader=function(){const r=headPrev.call(this);document.title='Village Observer V0.33F5A4';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33F5A4</strong>';const st=this.q?.('runtimeStatus'),z=ensure(this.world);if(st)st.textContent=`✓ V0.33F5A4 백과 재구축 · 고대 농장 ${z.stats.ancientFarmUpgradesCompleted} · 제재소 ${z.stats.sawmillCompleted} · 전시목표 repair ${z.stats.wartimeTargetInvariantRepairs}`;return r;};NS.UI.prototype.renderVillageContent=function(){return contentPrev.call(this);};NS.UI.prototype.renderCodex=function(){canonicalCodex(this);};}
